import * as ExcelJS from 'exceljs';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import type { Customer, Order, Product, User } from '../../pages/SalesmanAdmin_V1';

const formatCurrency = (val: number) => Number(val || 0).toFixed(2) + ' SAR';
const formatDate = (dateString: string) => new Date(dateString).toLocaleDateString('en-GB');
export const safeDateStr = () => {
    const d = new Date();
    return `${String(d.getDate()).padStart(2, '0')}-${String(d.getMonth() + 1).padStart(2, '0')}-${d.getFullYear()}`;
};

const LOGO_BASE64 = "data:image/png;base64,";
const COMPANY_NAME = "Mohammed Abdallah Sharbatly Co. ltd.";
const COMPANY_ADDRESS = "Al Faisaliyah, Jeddah 23442, Saudi Arabia"; // Placeholder address
const COMPANY_PHONE = "+966 12 345 6789";

const addErpHeader = (doc: jsPDF, title: string, date: string, additionalInfo?: string[]) => {
    // Add Logo
    try {
        doc.addImage(LOGO_BASE64, 'PNG', 14, 10, 25, 25);
    } catch (e) {}
    
    // Add Company Info
    doc.setFontSize(14);
    doc.setTextColor(30, 58, 138); // Dark Blue #1e3a8a
    doc.setFont('helvetica', 'bold');
    doc.text(COMPANY_NAME, 42, 16);
    
    doc.setFontSize(9);
    doc.setTextColor(100, 116, 139); // Slate 500
    doc.setFont('helvetica', 'normal');
    doc.text(COMPANY_ADDRESS, 42, 22);
    doc.text(`Phone: ${COMPANY_PHONE}`, 42, 27);
    
    // Add Document Title
    const pageWidth = doc.internal.pageSize.width || doc.internal.pageSize.getWidth();
    doc.setFontSize(18);
    doc.setTextColor(15, 23, 42); // Slate 900
    doc.setFont('helvetica', 'bold');
    doc.text(title, pageWidth - 14, 18, { align: 'right' });
    
    doc.setFontSize(10);
    doc.setTextColor(71, 85, 105); // Slate 600
    doc.setFont('helvetica', 'normal');
    doc.text(`Date: ${date}`, pageWidth - 14, 25, { align: 'right' });
    
    if (additionalInfo && additionalInfo.length > 0) {
        let y = 30;
        additionalInfo.forEach(info => {
            doc.text(info, pageWidth - 14, y, { align: 'right' });
            y += 5;
        });
    }
    
    // Add horizontal line
    doc.setDrawColor(226, 232, 240); // Slate 200
    doc.setLineWidth(0.5);
    doc.line(14, 38, pageWidth - 14, 38);
    
    return 45; // Return starting Y for table
};

const erpTableStyles = {
    theme: 'grid',
    styles: { 
        fontSize: 8, 
        cellPadding: 4,
        lineColor: [226, 232, 240],
        lineWidth: 0.1,
        font: 'helvetica',
        valign: 'middle',
        overflow: 'linebreak'
    },
    headStyles: { 
        fillColor: [30, 58, 138], // Dark Blue
        textColor: 255, 
        fontStyle: 'bold',
        halign: 'center'
    },
    alternateRowStyles: { fillColor: [248, 250, 252] }, // Slate 50
    margin: { top: 45, left: 14, right: 14, bottom: 20 },
    didDrawPage: (data: any) => {
        // Footer
        const doc = data.doc;
        const pageCount = doc.internal.getNumberOfPages();
        const pageWidth = doc.internal.pageSize.width;
        const pageHeight = doc.internal.pageSize.height;
        doc.setFontSize(8);
        doc.setTextColor(148, 163, 184);
        doc.text(`Generated by Inventory Suit ERP - ${COMPANY_NAME}`, 14, pageHeight - 10);
        doc.text(`Page ${pageCount}`, pageWidth - 14, pageHeight - 10, { align: 'right' });
    }
};

const downloadExcel = async (workbook: ExcelJS.Workbook, filename: string) => {
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    window.URL.revokeObjectURL(url);
};

export const generateWholesaleMarketSheet = async (orders: Order[], customers: Customer[], products: Product[], format: 'excel' | 'pdf', dateRangeStr: string) => {
    const dataMap: Record<string, Record<string, {price: number, qty: number}>> = {};
    customers.forEach(c => { dataMap[c.id] = {}; });
    const activeProducts = new Set<string>();

    orders.forEach(o => {
        if (!dataMap[o.customerId]) dataMap[o.customerId] = {};
        o.items.forEach(item => {
            activeProducts.add(item.productId);
            if (!dataMap[o.customerId][item.productId]) {
                dataMap[o.customerId][item.productId] = { price: item.price, qty: 0 };
            }
            dataMap[o.customerId][item.productId].qty += item.qty;
            dataMap[o.customerId][item.productId].price = item.price; 
        });
    });

    const productCols = products.filter(p => activeProducts.has(p.id)).sort((a,b) => a.name.localeCompare(b.name));
    const activeCustomers = customers.filter(c => productCols.some(p => dataMap[c.id]?.[p.id]?.qty > 0));

    if (format === 'excel') {
        const wb = new ExcelJS.Workbook();
        wb.creator = 'Inventory Suit V2';
        wb.created = new Date();
        const ws = wb.addWorksheet('Market Sheet', {
            pageSetup: { paperSize: 9, orientation: 'landscape', fitToPage: true, printTitlesRow: '1:3' }
        });

        ws.mergeCells(1, 1, 1, productCols.length + 1);
        const titleCell = ws.getCell(1, 1);
        titleCell.value = 'WHOLE SALE MARKET SHEET';
        titleCell.font = { name: 'Arial', size: 16, bold: true };
        titleCell.alignment = { horizontal: 'center', vertical: 'middle' };

        ws.mergeCells(2, 1, 2, productCols.length + 1);
        const dateCell = ws.getCell(2, 1);
        dateCell.value = `DATE: ${dateRangeStr} | ${COMPANY_NAME}`;
        dateCell.font = { name: 'Arial', size: 10, bold: true };
        dateCell.alignment = { horizontal: 'left' };
        
        ws.addRow([]);

        const headerRow = ws.getRow(4);
        headerRow.getCell(1).value = 'CUSTOMER';
        headerRow.getCell(1).font = { bold: true };
        headerRow.getCell(1).alignment = { horizontal: 'center', vertical: 'middle' };
        headerRow.getCell(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEFEFEF' } };
        headerRow.getCell(1).border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };

        productCols.forEach((p, idx) => {
            const cell = headerRow.getCell(idx + 2);
            cell.value = p.name;
            cell.font = { bold: true };
            cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFEFEFEF' } };
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        });
        headerRow.height = 30;

        activeCustomers.forEach((c, cIdx) => {
            const row = ws.getRow(5 + cIdx);
            row.height = 40; 
            
            const custCell = row.getCell(1);
            custCell.value = c.name;
            custCell.font = { bold: true };
            custCell.alignment = { vertical: 'middle', wrapText: true };
            custCell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };

            productCols.forEach((p, pIdx) => {
                const cell = row.getCell(pIdx + 2);
                const data = dataMap[c.id]?.[p.id];
                
                cell.border = { 
                    top: {style:'thin'}, 
                    left: {style:'thin'}, 
                    bottom: {style:'thin'}, 
                    right: {style:'thin'},
                    diagonal: { up: true, down: false, style: 'thin' }
                };
                
                if (data && data.qty > 0) {
                    cell.value = {
                        richText: [
                            { text: `Price: ${data.price.toFixed(2)}\n`, font: { size: 9, bold: true } },
                            { text: `            Qty: ${data.qty}`, font: { size: 9 } }
                        ]
                    };
                } else {
                    cell.value = '';
                }
                cell.alignment = { wrapText: true, vertical: 'justify' };
            });
        });

        ws.getColumn(1).width = 25;
        for (let i = 2; i <= productCols.length + 1; i++) {
            ws.getColumn(i).width = 15;
        }

        await downloadExcel(wb, `Wholesale_Market_Sheet_${safeDateStr()}.xlsx`);

    } else {
        const doc = new jsPDF({ orientation: 'landscape', format: 'a4' });
        const startY = addErpHeader(doc, 'WHOLE SALE MARKET SHEET', dateRangeStr);

        const head = [['CUSTOMER']];
        const subHead = [''];
        productCols.forEach(p => { head[0].push(p.name, ''); subHead.push('Price', 'Qty'); });
        
        const body: any[][] = [];
        activeCustomers.forEach(c => {
            const row = [c.name];
            productCols.forEach(p => {
                const cell = dataMap[c.id]?.[p.id];
                if (cell && cell.qty > 0) {
                    row.push(cell.price.toFixed(2), cell.qty.toString());
                } else {
                    row.push('', '');
                }
            });
            body.push(row);
        });

        (doc as any).autoTable({
            ...erpTableStyles,
            startY: startY,
            head: [head[0], subHead],
            body: body,
            styles: { ...erpTableStyles.styles, fontSize: 6, halign: 'center' },
            columnStyles: { 0: { halign: 'left', fontStyle: 'bold', minCellWidth: 30 } }
        });
        doc.save(`Wholesale_Market_Sheet_${safeDateStr()}.pdf`);
    }
};

export const generateCustomerOrderSheet = async (orders: Order[], format: 'excel' | 'pdf') => {
    if (format === 'excel') {
        const wb = new ExcelJS.Workbook();
        wb.creator = 'Inventory Suit V2';
        
        orders.forEach((o, index) => {
            let sheetName = `${o.customerName} - ${o.date}`.substring(0, 31).replace(/[\/*?\[\]]/g, '_');
            let finalName = sheetName;
            let counter = 1;
            while(wb.getWorksheet(finalName)) {
                finalName = `${sheetName}_${counter}`;
                counter++;
            }
            
            const ws = wb.addWorksheet(finalName, { pageSetup: { paperSize: 9, orientation: 'portrait', fitToPage: true } });
            
            ws.mergeCells('A1:F1');
            ws.getCell('A1').value = `${COMPANY_NAME} - CUSTOMER ORDER SHEET`;
            ws.getCell('A1').font = { size: 16, bold: true };
            ws.getCell('A1').alignment = { horizontal: 'center' };

            ws.getCell('A3').value = 'Order Number:';
            ws.getCell('B3').value = o.orderNumber || o.id;
            ws.getCell('E3').value = 'Order Date:';
            ws.getCell('F3').value = formatDate(o.date);
            
            ws.getCell('A4').value = 'Customer:';
            ws.getCell('B4').value = o.customerName;
            ws.getCell('E4').value = 'Status:';
            ws.getCell('F4').value = o.status;

            ws.getCell('A5').value = 'Salesman:';
            ws.getCell('B5').value = o.salespersonName;
            ws.getCell('E5').value = 'Payment:';
            ws.getCell('F5').value = o.paymentStatus;
            
            ['A3','A4','A5','E3','E4','E5'].forEach(cell => ws.getCell(cell).font = { bold: true });

            const headers = ['SKU', 'Product Name', 'Description', 'Qty', 'Unit Price', 'Total'];
            const headerRow = ws.getRow(7);
            headers.forEach((h, i) => {
                const cell = headerRow.getCell(i+1);
                cell.value = h;
                cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
                cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            });

            let subtotal = 0;
            o.items.forEach((item, idx) => {
                const total = item.qty * item.price;
                subtotal += total;
                const row = ws.getRow(8 + idx);
                row.values = [item.productId.substring(0,6), item.productName, '', item.qty, item.price, total];
                for(let i=1; i<=6; i++) {
                    row.getCell(i).border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                }
            });

            const finalRowIdx = 8 + o.items.length + 1;
            ws.getCell(`E${finalRowIdx}`).value = 'Subtotal';
            ws.getCell(`F${finalRowIdx}`).value = subtotal;
            ws.getCell(`E${finalRowIdx+1}`).value = 'Amount Paid';
            ws.getCell(`F${finalRowIdx+1}`).value = o.amountPaid || 0;
            ws.getCell(`E${finalRowIdx+2}`).value = 'Remaining';
            ws.getCell(`F${finalRowIdx+2}`).value = subtotal - (o.amountPaid || 0);

            [finalRowIdx, finalRowIdx+1, finalRowIdx+2].forEach(r => {
                ws.getCell(`E${r}`).font = { bold: true };
                ws.getCell(`F${r}`).font = { bold: true };
            });

            ws.getColumn(1).width = 15;
            ws.getColumn(2).width = 30;
            ws.getColumn(3).width = 20;
            ws.getColumn(4).width = 10;
            ws.getColumn(5).width = 15;
            ws.getColumn(6).width = 15;
        });

        await downloadExcel(wb, `Customer_Order_Sheets_${safeDateStr()}.xlsx`);
    } else {
        const doc = new jsPDF({ orientation: 'portrait', format: 'a4' });
        orders.forEach((o, index) => {
            if (index > 0) doc.addPage();
            
            const additionalInfo = [
                `Order Number: ${o.orderNumber || o.id}`,
                `Status: ${o.status}`,
                `Salesman: ${o.salespersonName}`
            ];
            const startY = addErpHeader(doc, 'CUSTOMER ORDER SHEET', formatDate(o.date), additionalInfo);
            
            doc.setFontSize(11);
            doc.setTextColor(15, 23, 42);
            doc.setFont('helvetica', 'bold');
            doc.text(`Customer: ${o.customerName}`, 14, startY);
            
            const body = o.items.map(item => [
                item.productId.substring(0,6), 
                item.productName, 
                item.qty.toString(), 
                formatCurrency(item.price), 
                formatCurrency(item.qty * item.price)
            ]);
            
            (doc as any).autoTable({
                ...erpTableStyles,
                startY: startY + 6,
                head: [['SKU', 'Product', 'Qty', 'Unit Price', 'Total']],
                body: body,
                columnStyles: {
                    0: { cellWidth: 25 },
                    1: { cellWidth: 'auto' },
                    2: { cellWidth: 20, halign: 'center' },
                    3: { cellWidth: 30, halign: 'right' },
                    4: { cellWidth: 35, halign: 'right' },
                }
            });
            
            const finalY = (doc as any).lastAutoTable.finalY || (startY + 6);
            doc.setFontSize(10);
            doc.setFont('helvetica', 'bold');
            doc.text(`Subtotal: ${formatCurrency(o.totalAmount)}`, 140, finalY + 10);
            doc.text(`Paid: ${formatCurrency(o.amountPaid || 0)}`, 140, finalY + 16);
            doc.text(`Remaining: ${formatCurrency(o.totalAmount - (o.amountPaid || 0))}`, 140, finalY + 22);
        });
        doc.save(`Customer_Order_Sheets_${safeDateStr()}.pdf`);
    }
};

export const generateDailyOrdersReport = async (orders: Order[], format: 'excel' | 'pdf') => {
    const head = ['Order Number', 'Customer', 'Items', 'Qty', 'Total Amount', 'Paid', 'Remaining', 'Status', 'Date'];
    const body = orders.map(o => [
        o.orderNumber || o.id.substring(0,6),
        o.customerName,
        o.items.length,
        o.items.reduce((s,i)=>s+i.qty, 0),
        o.totalAmount,
        o.amountPaid || 0,
        o.totalAmount - (o.amountPaid || 0),
        o.status,
        formatDate(o.date)
    ]);

    if (format === 'excel') {
        const wb = new ExcelJS.Workbook();
        const ws = wb.addWorksheet('Daily Orders', { pageSetup: { paperSize: 9, orientation: 'landscape', fitToPage: true } });
        
        ws.mergeCells(1, 1, 1, head.length);
        ws.getCell('A1').value = `${COMPANY_NAME} - DAILY ORDERS REPORT`;
        ws.getCell('A1').font = { size: 16, bold: true };
        ws.getCell('A1').alignment = { horizontal: 'center' };
        
        const headerRow = ws.getRow(3);
        head.forEach((h, i) => {
            const cell = headerRow.getCell(i+1);
            cell.value = h;
            cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        });

        body.forEach((rowData, rIdx) => {
            const row = ws.getRow(4 + rIdx);
            rowData.forEach((val, cIdx) => {
                const cell = row.getCell(cIdx + 1);
                cell.value = val;
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            });
        });

        ws.columns.forEach(col => { col.width = 18; });
        await downloadExcel(wb, `Daily_Orders_${safeDateStr()}.xlsx`);
    } else {
        const doc = new jsPDF({ orientation: 'landscape', format: 'a4' });
        const startY = addErpHeader(doc, 'DAILY ORDERS REPORT', safeDateStr());
        (doc as any).autoTable({ 
            ...erpTableStyles, 
            startY: startY, 
            head: [head], 
            body: body,
            columnStyles: {
                0: { fontStyle: 'bold' },
                4: { halign: 'right' },
                5: { halign: 'right' },
                6: { halign: 'right' }
            }
        });
        doc.save(`Daily_Orders_${safeDateStr()}.pdf`);
    }
};

export const generateProductSalesReport = async (orders: Order[], products: Product[], format: 'excel' | 'pdf') => {
    const pStats: Record<string, {qty:number, revenue:number, customers:Set<string>}> = {};
    orders.forEach(o => {
        o.items.forEach(i => {
            if(!pStats[i.productId]) pStats[i.productId] = {qty:0, revenue:0, customers:new Set()};
            pStats[i.productId].qty += i.qty;
            pStats[i.productId].revenue += (i.qty * i.price);
            pStats[i.productId].customers.add(o.customerId);
        });
    });

    const head = ['SKU', 'Product Name', 'Quantity Sold', 'Average Price', 'Revenue', 'Unique Buyers'];
    const body = products.filter(p => pStats[p.id]).map(p => {
        const st = pStats[p.id];
        return [p.code || '-', p.name, st.qty, (st.revenue/st.qty).toFixed(2), st.revenue.toFixed(2), st.customers.size];
    }).sort((a,b) => parseFloat(b[4] as string) - parseFloat(a[4] as string));

    if (format === 'excel') {
        const wb = new ExcelJS.Workbook();
        const ws = wb.addWorksheet('Product Sales', { pageSetup: { orientation: 'portrait', fitToPage: true } });
        
        ws.mergeCells(1, 1, 1, head.length);
        ws.getCell('A1').value = `${COMPANY_NAME} - PRODUCT SALES REPORT`;
        ws.getCell('A1').font = { size: 16, bold: true };
        ws.getCell('A1').alignment = { horizontal: 'center' };
        
        const headerRow = ws.getRow(3);
        head.forEach((h, i) => {
            const cell = headerRow.getCell(i+1);
            cell.value = h;
            cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        });

        body.forEach((rowData, rIdx) => {
            const row = ws.getRow(4 + rIdx);
            rowData.forEach((val, cIdx) => {
                const cell = row.getCell(cIdx + 1);
                cell.value = val;
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            });
        });

        ws.getColumn(1).width = 15;
        ws.getColumn(2).width = 30;
        ws.getColumn(3).width = 15;
        ws.getColumn(4).width = 15;
        ws.getColumn(5).width = 15;
        ws.getColumn(6).width = 15;

        await downloadExcel(wb, `Product_Sales_${safeDateStr()}.xlsx`);
    } else {
        const doc = new jsPDF({ orientation: 'portrait', format: 'a4' });
        const startY = addErpHeader(doc, 'PRODUCT SALES REPORT', safeDateStr());
        (doc as any).autoTable({ 
            ...erpTableStyles, 
            startY: startY, 
            head: [head], 
            body: body,
            columnStyles: {
                0: { fontStyle: 'bold' },
                2: { halign: 'center' },
                3: { halign: 'right' },
                4: { halign: 'right' },
                5: { halign: 'center' }
            }
        });
        doc.save(`Product_Sales_${safeDateStr()}.pdf`);
    }
};

export const generateCustomerSummaryReport = async (orders: Order[], customers: Customer[], format: 'excel' | 'pdf') => {
    const head = ['Customer', 'Total Orders', 'Total Qty', 'Total Amount', 'Paid Amount', 'Remaining Balance'];
    
    const cStats: Record<string, {orders:number, qty:number, amount:number, paid:number}> = {};
    orders.forEach(o => {
        if(!cStats[o.customerId]) cStats[o.customerId] = {orders:0, qty:0, amount:0, paid:0};
        cStats[o.customerId].orders += 1;
        cStats[o.customerId].qty += o.items.reduce((s,i)=>s+i.qty, 0);
        cStats[o.customerId].amount += o.totalAmount;
        cStats[o.customerId].paid += (o.amountPaid || 0);
    });

    const body = customers.map(c => {
        const st = cStats[c.id] || {orders:0, qty:0, amount:0, paid:0};
        return [c.name, st.orders, st.qty, st.amount.toFixed(2), st.paid.toFixed(2), Number(c.remainingBalance || 0).toFixed(2)];
    }).sort((a,b) => parseFloat(b[3] as string) - parseFloat(a[3] as string));

    if (format === 'excel') {
        const wb = new ExcelJS.Workbook();
        const ws = wb.addWorksheet('Customer Summary', { pageSetup: { orientation: 'landscape', fitToPage: true } });
        
        ws.mergeCells(1, 1, 1, head.length);
        ws.getCell('A1').value = `${COMPANY_NAME} - CUSTOMER SUMMARY REPORT`;
        ws.getCell('A1').font = { size: 16, bold: true };
        ws.getCell('A1').alignment = { horizontal: 'center' };
        
        const headerRow = ws.getRow(3);
        head.forEach((h, i) => {
            const cell = headerRow.getCell(i+1);
            cell.value = h;
            cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        });

        body.forEach((rowData, rIdx) => {
            const row = ws.getRow(4 + rIdx);
            rowData.forEach((val, cIdx) => {
                const cell = row.getCell(cIdx + 1);
                cell.value = val;
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            });
        });

        ws.columns.forEach(col => { col.width = 20; });
        await downloadExcel(wb, `Customer_Summary_${safeDateStr()}.xlsx`);
    } else {
        const doc = new jsPDF({ orientation: 'landscape', format: 'a4' });
        const startY = addErpHeader(doc, 'CUSTOMER SUMMARY REPORT', safeDateStr());
        (doc as any).autoTable({ 
            ...erpTableStyles, 
            startY: startY, 
            head: [head], 
            body: body,
            columnStyles: {
                0: { fontStyle: 'bold' },
                1: { halign: 'center' },
                2: { halign: 'center' },
                3: { halign: 'right' },
                4: { halign: 'right' },
                5: { halign: 'right' }
            }
        });
        doc.save(`Customer_Summary_${safeDateStr()}.pdf`);
    }
};

export const generateSalesmanPerformanceReport = async (orders: Order[], users: User[], format: 'excel' | 'pdf') => {
    const head = ['Salesman', 'Orders', 'Total Qty', 'Sales Amount', 'Collection Amount', 'Avg Order Value'];
    
    const sStats: Record<string, {orders:number, qty:number, amount:number, collected:number}> = {};
    orders.forEach(o => {
        if(!sStats[o.salespersonId]) sStats[o.salespersonId] = {orders:0, qty:0, amount:0, collected:0};
        sStats[o.salespersonId].orders += 1;
        sStats[o.salespersonId].qty += o.items.reduce((s,i)=>s+i.qty, 0);
        sStats[o.salespersonId].amount += o.totalAmount;
        sStats[o.salespersonId].collected += (o.amountPaid || 0);
    });

    const salesmen = users.filter(u => u.role === 'SALESPERSON');
    
    const body = salesmen.map(u => {
        const st = sStats[u.id] || {orders:0, qty:0, amount:0, collected:0};
        return [u.name, st.orders, st.qty, st.amount.toFixed(2), st.collected.toFixed(2), st.orders > 0 ? (st.amount/st.orders).toFixed(2) : 0];
    });

    if (format === 'excel') {
        const wb = new ExcelJS.Workbook();
        const ws = wb.addWorksheet('Salesman Performance', { pageSetup: { orientation: 'landscape', fitToPage: true } });
        
        ws.mergeCells(1, 1, 1, head.length);
        ws.getCell('A1').value = `${COMPANY_NAME} - SALESMAN PERFORMANCE REPORT`;
        ws.getCell('A1').font = { size: 16, bold: true };
        ws.getCell('A1').alignment = { horizontal: 'center' };
        
        const headerRow = ws.getRow(3);
        head.forEach((h, i) => {
            const cell = headerRow.getCell(i+1);
            cell.value = h;
            cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        });

        body.forEach((rowData, rIdx) => {
            const row = ws.getRow(4 + rIdx);
            rowData.forEach((val, cIdx) => {
                const cell = row.getCell(cIdx + 1);
                cell.value = val;
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            });
        });

        ws.columns.forEach(col => { col.width = 20; });
        await downloadExcel(wb, `Salesman_Performance_${safeDateStr()}.xlsx`);
    } else {
        const doc = new jsPDF({ orientation: 'landscape', format: 'a4' });
        const startY = addErpHeader(doc, 'SALESMAN PERFORMANCE REPORT', safeDateStr());
        (doc as any).autoTable({ 
            ...erpTableStyles, 
            startY: startY, 
            head: [head], 
            body: body,
            columnStyles: {
                0: { fontStyle: 'bold' },
                1: { halign: 'center' },
                2: { halign: 'center' },
                3: { halign: 'right' },
                4: { halign: 'right' },
                5: { halign: 'right' }
            }
        });
        doc.save(`Salesman_Performance_${safeDateStr()}.pdf`);
    }
};
